import java.util.*;
class Patient {final String name;final int severity;final long arrival;Patient(String n,int s,long a){if(s<1||s>5)throw new IllegalArgumentException("Severity must be 1..5");name=n;severity=s;arrival=a;}public String toString(){return name+"(S"+severity+",#"+arrival+")";}}
public class Triage {private long counter=0;private final PriorityQueue<Patient> queue=new PriorityQueue<>(Comparator.comparingInt((Patient p)->p.severity).thenComparingLong(p->p.arrival));void admit(String n,int s){queue.add(new Patient(n,s,counter++));}Patient next(){return queue.poll();}public static void main(String[]x){Triage t=new Triage();t.admit("Asha",3);t.admit("Bala",1);t.admit("Chitra",2);t.admit("Dev",1);t.admit("Esha",5);t.admit("Farah",3);t.admit("Gopal",4);t.admit("Hari",2);System.out.println("Treatment order:");Patient p;while((p=t.next())!=null)System.out.println(p);System.out.println("PriorityQueue offer/poll O(log n); peek O(1); storage O(n). Aging can periodically improve severity based on waiting duration.");}}
